const back: OffscreenCanvas = new OffscreenCanvas(w, h);

function present(
  ctx: ImageBitmapRenderingContext,
  draw: (c: OffscreenCanvasRenderingContext2D) => void,
): void {
  draw(back.getContext("2d")!);               // whole frame on the back buffer
  ctx.transferFromImageBitmap(back.transferToImageBitmap());
}
